const events = apptRaw.events || apptRaw.data || [];
const totalAppts = events.length;
const apptStatus = { booked: 0, confirmed: 0, showed: 0, noshow: 0, cancelled: 0, other: 0 };
events.forEach(evt => {
  const s = (evt.appointmentStatus || evt.status || '').toLowerCase();
  if (s.includes('book') || s === 'new') apptStatus.booked++;
  else if (s.includes('confirm')) apptStatus.confirmed++;
  else if (s.includes('show') && !s.includes('no')) apptStatus.showed++;
  else if (s.includes('noshow') || s.includes('no_show') || s.includes('no-show')) apptStatus.noshow++;
  else if (s.includes('cancel')) apptStatus.cancelled++;
  else apptStatus.other++;
});
const showRate = totalAppts > 0 ? ((apptStatus.showed / totalAppts) * 100).toFixed(1) : '0.0';

// CALLS
const convos = callsRaw.conversations || callsRaw.data || [];
const totalCalls = convos.length;
let inbound = 0, outbound = 0, missed = 0, totalDurSec = 0;
convos.forEach(c => {
  const dir = (c.direction || c.lastMessageDirection || '').toLowerCase();
  if (dir.includes('inbound') || dir.includes('incoming')) inbound++;
  else outbound++;
  const st = (c.callStatus || c.status || '').toLowerCase();
  if (st.includes('missed') || st.includes('no-answer') || st.includes('noanswer')) missed++;
  if (c.callDuration || c.duration) totalDurSec += Number(c.callDuration || c.duration || 0);
});
